import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void dwconv2d_k1_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int Win,
    int K, int stride, int padding, int dilation,
    int Hout, int Wout)
{
  constexpr int OH_TILE    = 64;
  constexpr int OW_TILE    = 32;
  constexpr int VEC        = 4;
  constexpr int OW_THREADS = OW_TILE / VEC;
  constexpr int CcPerBlock = 2;
  constexpr int TY_THREADS = 8;
  constexpr int ROWS_PER_THREAD = OH_TILE / TY_THREADS;
  const int tx = threadIdx.x; // along output width group (0..OW_THREADS-1)
  const int ty = threadIdx.y; // along output height sub-tile (0..TY_THREADS-1)
  const int tid = ty * OW_THREADS + tx;
  const int nthreads = TY_THREADS * OW_THREADS;
  const int c_tile_count = (C + CcPerBlock - 1) / CcPerBlock;
  const int n         = blockIdx.z / c_tile_count;
  const int c_tile    = blockIdx.z % c_tile_count;
  const int c_base    = c_tile * CcPerBlock;
  const int ow_base = (int)blockIdx.x * OW_TILE;
  const int oh_base = (int)blockIdx.y * OH_TILE;
  const int ow_local0 = tx * VEC;
  const int ow0 = ow_base + ow_local0;
  // Memory strides
  const int64_t sXn = (int64_t)C * H * Win;
  const int64_t sXc = (int64_t)H * Win;
  const int64_t sXh = (int64_t)Win;
  const int64_t sYn = (int64_t)C * Hout * Wout;
  const int64_t sYc = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;
  // Global tensors using Cute
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(C, H, Win),
      make_stride(sXc, sXh, Int<1>{})
  );
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C, K),
      make_stride(K, Int<1>{})
  );
  // Dynamic shared memory layout:
  //  [0, CcPerBlock*K)                                          -> weights sW[cc][kk]
  //  [CcPerBlock*K, CcPerBlock*K + CcPerBlock*IH_TILE*OW_TILE)   -> input tile sIn[cc][ih_local][ow_local]
  extern __shared__ unsigned char smem_raw[];
  T* sW  = reinterpret_cast<T*>(smem_raw);
  size_t sW_bytes = (size_t)CcPerBlock * K * sizeof(T);
  size_t sIn_offset = (sW_bytes + 15) & ~(size_t)15;
  T* sIn = reinterpret_cast<T*>(smem_raw + sIn_offset);
  const int IH_TILE = (OH_TILE - 1) * stride + (K - 1) * dilation + 1;
  // Load weight chunk for CcPerBlock channels into shared memory
  for (int idx = tid; idx < CcPerBlock * K; idx += nthreads) {
    int cc = idx / K;
    int kk = idx % K;
    int c  = c_base + cc;
    T wval = T(0);
    if (c < C) {
      wval = mW(c, kk);
    }
    sW[cc * K + kk] = wval;
  }
  // Stage the reusable input tile (covers all K taps for OH_TILE output rows)
  const int ih_row_base = oh_base * stride - padding;
  if (stride == 1) {
    // Vectorized staging using 128-bit (float4) loads along width when aligned (stride==1 is contiguous)
    constexpr int OW_TILE_VEC = OW_TILE / VEC;
    const int in_tile_elems_vec = CcPerBlock * IH_TILE * OW_TILE_VEC;
    for (int idx = tid; idx < in_tile_elems_vec; idx += nthreads) {
      int cc        = idx / (IH_TILE * OW_TILE_VEC);
      int rem       = idx % (IH_TILE * OW_TILE_VEC);
      int ih_local  = rem / OW_TILE_VEC;
      int owv_local = rem % OW_TILE_VEC;
      int c   = c_base + cc;
      int ih  = ih_row_base + ih_local * dilation;
      int ow_local0s = owv_local * VEC;
      int owg0 = ow_base + ow_local0s;
      int iw0  = owg0 - padding;
      float4 xv = make_float4(0.f, 0.f, 0.f, 0.f);
      bool row_ok = (c < C) && (ih >= 0) && (ih < H);
      int64_t off = (int64_t)c * sXc + (int64_t)ih * sXh + iw0;
      bool full_in_bounds = row_ok && (iw0 >= 0) && ((iw0 + VEC - 1) < Win) && ((off & 3) == 0);
      if (full_in_bounds) {
        const T* ptr = X + (int64_t)n * sXn + off;
        xv = *reinterpret_cast<const float4*>(ptr);
      } else if (row_ok) {
        float vals[VEC] = {0.f, 0.f, 0.f, 0.f};
        #pragma unroll
        for (int q = 0; q < VEC; ++q) {
          int iw = iw0 + q;
          if (iw >= 0 && iw < Win) {
            vals[q] = (float)mX(c, ih, iw);
          }
        }
        xv = make_float4(vals[0], vals[1], vals[2], vals[3]);
      }
      T* dst = &sIn[cc * IH_TILE * OW_TILE + ih_local * OW_TILE + ow_local0s];
      *reinterpret_cast<float4*>(dst) = xv;
    }
  } else {
    const int in_tile_elems = CcPerBlock * IH_TILE * OW_TILE;
    for (int idx = tid; idx < in_tile_elems; idx += nthreads) {
      int cc       = idx / (IH_TILE * OW_TILE);
      int rem      = idx % (IH_TILE * OW_TILE);
      int ih_local = rem / OW_TILE;
      int ow_local = rem % OW_TILE;
      int c   = c_base + cc;
      int ih  = ih_row_base + ih_local * dilation;
      int owg = ow_base + ow_local;
      int iw  = owg * stride - padding;
      T xval = T(0);
      if (c < C && ih >= 0 && ih < H && iw >= 0 && iw < Win) {
        xval = mX(c, ih, iw);
      }
      sIn[cc * IH_TILE * OW_TILE + ih_local * OW_TILE + ow_local] = xval;
    }
  }
  __syncthreads();
  #pragma unroll
  for (int r = 0; r < ROWS_PER_THREAD; ++r) {
    int oh_local = ty + r * TY_THREADS;
    int oh = oh_base + oh_local;
    if (oh >= Hout) continue;
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      if (c >= C) continue;
      float bval = 0.0f;
      if (B != nullptr) {
        bval = (float)B[c];
      }
      float acc[VEC];
      #pragma unroll
      for (int q = 0; q < VEC; ++q) acc[q] = bval;
      #pragma unroll
      for (int kk = 0; kk < K; ++kk) {
        int ih_local = oh_local * stride + kk * dilation;
        float wval = (float)sW[cc * K + kk];
        const T* srow = &sIn[cc * IH_TILE * OW_TILE + ih_local * OW_TILE + ow_local0];
        #pragma unroll
        for (int q = 0; q < VEC; ++q) {
          acc[q] += (float)srow[q] * wval;
        }
      }
      int64_t base_off = (int64_t)c * sYc + (int64_t)oh * sYh + ow0;
      T* ydst = Y + (int64_t)n * sYn + base_off;
      bool full_tile = (ow0 + VEC - 1) < Wout;
      bool aligned = ((base_off & 3) == 0);
      if (full_tile && aligned) {
        float4 yv = make_float4(acc[0], acc[1], acc[2], acc[3]);
        *reinterpret_cast<float4*>(ydst) = yv;
      } else {
        #pragma unroll
        for (int q = 0; q < VEC; ++q) {
          int oww = ow0 + q;
          if (oww < Wout) {
            ydst[q] = static_cast<T>(acc[q]);
          }
        }
      }
    }
  }
}

torch::Tensor dwconv2d_depthwise_k1_forward(torch::Tensor x,
                                            torch::Tensor w,
                                            c10::optional<torch::Tensor> b,
                                            int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [C, 1, K, 1] for depthwise conv (groups=C)");

  int64_t N   = x.size(0);
  int64_t C   = x.size(1);
  int64_t H   = x.size(2);
  int64_t Win = x.size(3);

  TORCH_CHECK(w.size(0) == C, "w.size(0) must equal C");
  TORCH_CHECK(w.size(1) == 1, "w.size(1) must be 1 for depthwise");
  TORCH_CHECK(w.size(3) == 1, "w.size(3) must be 1 for (kernel_width=1)");
  int64_t K = w.size(2);

  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Hout = (H + 2 * padding - dilation * (K - 1) - 1) / stride + 1;
  int64_t Wout = (Win + 2 * padding - dilation * (1 - 1) - 1) / stride + 1; // kw=1
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must be [C]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, C, Hout, Wout}, x.options());

  constexpr int OH_TILE = 64;
  constexpr int OW_TILE = 32;
  constexpr int VEC = 4;
  constexpr int OW_THREADS = OW_TILE / VEC;
  constexpr int CcPerBlock = 2;
  constexpr int TY_THREADS = 8;
  dim3 block(OW_THREADS, TY_THREADS);
  dim3 grid(
      (unsigned)((Wout + OW_TILE - 1) / OW_TILE),
      (unsigned)((Hout + OH_TILE - 1) / OH_TILE),
      (unsigned)(N * ((C + CcPerBlock - 1) / CcPerBlock))
  );
  const int IH_TILE = (OH_TILE - 1) * (int)stride + ((int)K - 1) * (int)dilation + 1;
  size_t sW_bytes_host = (size_t)(CcPerBlock * K) * sizeof(float);
  size_t sIn_offset_host = (sW_bytes_host + 15) & ~(size_t)15;
  size_t sIn_bytes_host = (size_t)(CcPerBlock * IH_TILE * OW_TILE) * sizeof(float);
  size_t smem_bytes = sIn_offset_host + sIn_bytes_host;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  dwconv2d_k1_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)C, (int)H, (int)Win,
      (int)K, (int)stride, (int)padding, (int)dilation,
      (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "dwconv2d_k1_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

dwconv2d_ext = load_inline(
    name="cute_dwconv2d_k1_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["dwconv2d_depthwise_k1_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/root/cutegen_test/cutegen/cutlass/include",
        "/root/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Depthwise 2D convolution with vertical asymmetric kernel (kernel_size x 1),
    implemented with a single custom CUDA kernel using CuTe.
    """
    def __init__(self,
                 in_channels: int,
                 kernel_size: int,
                 stride: int = 1,
                 padding: int = 0,
                 dilation: int = 1,
                 bias: bool = False) -> None:
        super().__init__()
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert isinstance(stride, int) and stride >= 1
        assert isinstance(padding, int) and padding >= 0
        assert isinstance(dilation, int) and dilation >= 1

        self.in_channels = int(in_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)

        # Depthwise: groups = in_channels, out_channels = in_channels
        C = self.in_channels
        K = self.kernel_size
        # Weight shape matches PyTorch depthwise layout: [C_out, C_in/groups, Kh, Kw] with groups=C => [C,1,K,1]
        self.weight = nn.Parameter(torch.empty(C, 1, K, 1))
        if bias:
            self.bias = nn.Parameter(torch.empty(C))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = dwconv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.kernel_size  # depthwise per-channel fan_in equals kernel_size along H (Kw=1)
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.dwconv2d_depthwise_k1_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

